//Create thumbnail image from a user controlprivate Image GetControlThumb(Control control, int thumbSize){    Bitmap imgLarge = new Bitmap(control.Bounds.Width, control.Bounds.Height);    using (Graphics g = Graphics.FromImage(imgLarge))    {        g.CopyFromScreen(            control.Parent.PointToScreen(new Point(control.Left, control.Top)),            new Point(0, 0),            new Size(control.Bounds.Width, control.Bounds.Height));    }    Size size;    if (control.Width > control.Height)    {        size = new Size(thumbSize, (int)(thumbSize * (float)control.Height / (float)control.Width));    }    else    {        size = new Size((int)(thumbSize * (float)control.Width / (float)control.Height), thumbSize);    }    Image imgSmall = imgLarge.GetThumbnailImage(size.Width, size.Height, new Image.GetThumbnailImageAbort(delegate { return false; }), IntPtr.Zero);    imgLarge.Dispose();    return imgSmall;}myPictureBox.Image = GetControlThumb(someControl, 100);//ORPlease check the following code, its origin is here and some comments are added. The general idea is to capture the screen part of the target control and store it into a Bitmap object, and then use Image.GetThumbnailImage() method to get the thumbnail.     You can take the following steps to test this approach:    1. Create a WinForm project;    2. Drag a PictureBox control onto the Form, name it "pictureBox1";    3. Drag a Button control onto the Form, name it "button1";    4. add the following code, and wire the button1 click event;    5. Run the program. Click the button1 and the thumbnail of button1 will be displayed in picturebox1;private void button1_Click(object sender, EventArgs e)        {            //Sample usage            pictureBox1.Image = GetControlThumb(this.button1, pictureBox1.Width);        }        private Image GetControlThumb(Control target_control, int thumbSize)        {            //Build a Bitmap object according to the size of the target_control            Bitmap imgLarge = new Bitmap(target_control.Bounds.Width, target_control.Bounds.Height);            //Create a Graphics object from the Bitmap object and,            //Capture the screen part of the target_control into the Graphics object            using (Graphics g = Graphics.FromImage(imgLarge))            {                g.CopyFromScreen(                    target_control.Parent.PointToScreen(new Point(target_control.Left, target_control.Top)),                    new Point(0, 0),                    new Size(target_control.Bounds.Width, target_control.Bounds.Height));            }            Size size;            //Scaling to fit the thumbSize            if (target_control.Width > target_control.Height)            {                size = new Size(thumbSize, (int)(thumbSize * (float)target_control.Height / (float)target_control.Width));            }            else            {                size = new Size((int)(thumbSize * (float)target_control.Width / (float)target_control.Height), thumbSize);            }            //Get the thumbnail            Image imgSmall = imgLarge.GetThumbnailImage(size.Width, size.Height, new Image.GetThumbnailImageAbort(delegate { return false; }), IntPtr.Zero);            imgLarge.Dispose();            return imgSmall;        } 